with flagged as (select *, case when lag(reading_ts) over (partition by device_code order by reading_ts, id) is null or reading_ts > lag(reading_ts) over (partition by device_code order by reading_ts, id) + interval '45' minute then 1 else 0 end as is_new_burst from device_readings), islands as (select *, sum(is_new_burst) over (partition by device_code order by reading_ts, id rows between unbounded preceding and current row) as burst_id from flagged) select id, device_code, reading_ts, temp_c, humidity, pressure, status_bits, firmware, is_new_burst from islands order by id desc limit 5;
